  ) values (
    v_skill_id, 1, 'Comparar movimentos a partir de um referencial', 'Determinar a rapidez relativa a partir de um referencial explícito e dos sentidos dos movimentos. A explicação usa dados explícitos e distingue o modelo físico de conclusões que os dados não autorizam.', '## Comece pelo referencial
Velocidade descreve posição mudando em relação a um referencial. Para comparar dois móveis, declare quem observa e represente os sentidos com setas.

## Mesmo sentido e sentidos opostos
Se dois móveis seguem no mesmo sentido, o módulo da velocidade relativa é a diferença entre os módulos. A 18 km/h e 12 km/h no mesmo sentido, um vê o outro afastar-se a 6 km/h. Em sentidos opostos, os módulos se somam: 10 km/h e 5 km/h dão aproximação relativa de 15 km/h.

## Encontro e afastamento
Se a distância inicial e as velocidades forem constantes, tempo de encontro = distância ÷ rapidez relativa. Não some velocidades no mesmo sentido, nem subtraia quando os móveis se aproximam em sentidos opostos. Unifique as unidades antes de comparar.',
    'Dois ciclistas estão separados por 30 km e se aproximam a 10 km/h e 5 km/h. A rapidez de aproximação é 15 km/h; o encontro ocorre em 30 ÷ 15 = 2 h.', array['Anote dados e unidades antes de calcular.', 'Declare o referencial ou o eixo adotado.', 'Mostre a relação usada e confira se a conclusão responde ao enunciado.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-physics-relative-speed-sequence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler tabelas de valores.","Calcular diferenças e razões simples."],"key_concepts":["referencial","sentido do movimento","velocidade relativa","aproximação","afastamento"],"progression":[{"stage":"DIAGNOSTIC","focus":"Verificar ideias iniciais e leitura das grandezas.","questionIds":["v5-physics-relative-speed-01","v5-physics-relative-speed-02","v5-physics-relative-speed-03","v5-physics-relative-speed-04"]},{"stage":"PRACTICE","focus":"Aplicar o critério com apoio gradual.","questionIds":["v5-physics-relative-speed-05","v5-physics-relative-speed-06","v5-physics-relative-speed-07","v5-physics-relative-speed-08","v5-physics-relative-speed-09","v5-physics-relative-speed-10","v5-physics-relative-speed-11","v5-physics-relative-speed-12","v5-physics-relative-speed-13","v5-physics-relative-speed-14","v5-physics-relative-speed-15","v5-physics-relative-speed-16"]},{"stage":"TRANSFER","focus":"Interpretar dados em contextos e justificar a escolha do modelo.","questionIds":["v5-physics-relative-speed-17","v5-physics-relative-speed-18","v5-physics-relative-speed-19","v5-physics-relative-speed-20","v5-physics-relative-speed-21","v5-physics-relative-speed-22","v5-physics-relative-speed-23","v5-physics-relative-speed-24"]},{"stage":"CONSOLIDATION","focus":"Localizar e corrigir erros de raciocínio.","questionIds":["v5-physics-relative-speed-25","v5-physics-relative-speed-26","v5-physics-relative-speed-27","v5-physics-relative-speed-28","v5-physics-relative-speed-29","v5-physics-relative-speed-30"]},{"stage":"REVIEW","focus":"Retomar conceitos com dados e representações variadas.","questionIds":["v5-physics-relative-speed-31","v5-physics-relative-speed-32","v5-physics-relative-speed-33","v5-physics-relative-speed-34","v5-physics-relative-speed-35","v5-physics-relative-speed-36","v5-physics-relative-speed-37","v5-physics-relative-speed-38","v5-physics-relative-speed-39","v5-physics-relative-speed-40"]}],"micro_explanations":[{"trigger":"CHOOSE_FRAME","text":"Declare quem observa antes de comparar as velocidades."},{"trigger":"SAME_DIRECTION","text":"No mesmo sentido, a rapidez relativa é a diferença dos módulos."},{"trigger":"OPPOSITE_DIRECTION","text":"Em sentidos opostos, a rapidez de aproximação ou afastamento soma os módulos."},{"trigger":"DRAW_ARROWS","text":"Setas tornam visível se os móveis se aproximam ou se afastam."},{"trigger":"MEETING_TIME","text":"Tempo de encontro é a distância inicial dividida pela rapidez relativa."},{"trigger":"MATCH_UNITS","text":"Compare velocidades somente depois de converter para a mesma unidade."}],"remediations":[{"id":"SET_REFERENCE","misconception":"Fazer conta sem indicar quem observa.","prompt":"Marque o referencial e escreva os sentidos dos dois movimentos."},{"id":"SAME_SENSE_SUBTRACT","misconception":"Somar velocidades que apontam para o mesmo sentido.","prompt":"Considere a diferença dos módulos: o móvel mais rápido alcança o mais lento à taxa dessa diferença."},{"id":"OPPOSITE_SENSE_ADD","misconception":"Subtrair movimentos em sentidos opostos.","prompt":"Quando a distância entre eles diminui, some os módulos para obter a rapidez relativa."},{"id":"DISTANCE_OVER_RELATIVE","misconception":"Dividir distância por apenas uma velocidade no encontro.","prompt":"Calcule primeiro a rapidez relativa e depois divida a separação inicial por ela."},{"id":"CONVERT_FIRST","misconception":"Comparar km/h e m/s diretamente.","prompt":"Converta uma das velocidades e mantenha a unidade até o resultado."},{"id":"SEPARATE_DIRECTION_MAGNITUDE","misconception":"Confundir módulo com sentido.","prompt":"Informe a rapidez relativa como módulo e descreva separadamente o sentido do movimento relativo."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"TecEscola","title":"Conjunto de medidas e situações de movimento sintéticas","license":"Dados, enunciados e explicações autorais; cenários hipotéticos, sem alegação de fonte oficial."}],"copyright_note":"Questões, valores, explicações e atividade são autorais e sintéticos. Revisão pedagógica pendente; alinhamento oficial não reivindicado.","authentic_activities":[{"id":"v5-physics-relative-speed-motion-audit","title":"Auditoria de registros: comparar movimentos a partir de um referencial","objective":"Determinar a rapidez relativa a partir de um referencial explícito e dos sentidos dos movimentos.","context":"Use tabelas sintéticas elaboradas para a atividade, com medidas fictícias e unidades explícitas.","materials":["Tabela de dados sintéticos","Papel quadriculado ou planilha acessível","Calculadora opcional"],"instructions":"Em pares, organize os dados, identifique o referencial ou eixo, calcule as grandezas solicitadas e escreva uma conclusão limitada às evidências. Em seguida, confira um cálculo de outro grupo e explique eventual divergência.","evidence":"Registro reproduzível dos dados, operações com unidades e justificativa baseada nas medidas fornecidas.","privacyGuard":"Utilize apenas dados sintéticos. Não registrar trajetos, velocidade, rotina ou localização de estudantes.","rubric":[{"criterion":"Leitura dos dados","emerging":"Troca valores, unidades ou intervalos.","developing":"Organiza os dados com uma orientação.","proficient":"Organiza todos os pares e unidades corretamente."},{"criterion":"Modelo e cálculo","emerging":"Escolhe operação sem relacioná-la aos dados.","developing":"Aplica a relação correta com apoio.","proficient":"Justifica o modelo e calcula com sinais e unidades coerentes."},{"criterion":"Conclusão","emerging":"Afirma algo não sustentado pelo registro.","developing":"Conclui a partir de parte dos dados.","proficient":"Explica a conclusão e seus limites usando as evidências."}]}],"source_question_feedback":[{"questionId":"v3-physics-physics_average_speed-7","hint":"Declare os sentidos e o referencial antes de decidir entre somar ou subtrair os módulos.","errorFocus":"PHYSICS_RELATIVE_SPEED"}],"objective":"Determinar a rapidez relativa a partir de um referencial explícito e dos sentidos dos movimentos.","common_mistake":"Ignorar o referencial, inverter a variação, misturar unidades ou concluir mais do que os dados mostram.","estimated_minutes":28}'::jsonb
