  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-physics-relative-speed-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"CICLISTAS_MESMO_SENTIDO","statement":"Dois móveis seguem no mesmo sentido, com velocidades constantes de 18 km/h e 12 km/h. Qual é o módulo da velocidade relativa entre eles?","explanation":"Como os sentidos são iguais, a rapidez relativa é 18 − 12 = 6 km/h. para um observador parado em relação ao solo define o referencial; para o módulo da velocidade relativa, sentidos iguais levam à diferença dos módulos e sentidos opostos levam à soma.","hint":"Desenhe uma seta para cada movimento e escolha quem observa. Mesmo sentido: compare os módulos; sentidos opostos: some os módulos.","errorFocus":"SAME_DIRECTION_SPEEDS_MUST_BE_SUBTRACTED","options":["6 km/h","30 km/h","18 km/h","4 unidades"],"correctAnswer":"6 km/h","misconceptions":{"30 km/h":["SAME_DIRECTION_SPEEDS_MUST_BE_SUBTRACTED"]},"position":1},{"id":"v5-physics-relative-speed-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"CORREDORES_MESMO_SENTIDO","statement":"Dois móveis seguem no mesmo sentido, com velocidades constantes de 9 km/h e 5 km/h. Qual é o módulo da velocidade relativa entre eles?","explanation":"Como os sentidos são iguais, a rapidez relativa é 9 − 5 = 4 km/h. em relação ao primeiro móvel define o referencial; para o módulo da velocidade relativa, sentidos iguais levam à diferença dos módulos e sentidos opostos levam à soma.","hint":"Desenhe uma seta para cada movimento e escolha quem observa. Mesmo sentido: compare os módulos; sentidos opostos: some os módulos.","errorFocus":"SAME_DIRECTION_SPEEDS_MUST_BE_SUBTRACTED","options":["14 km/h","4 km/h","9 km/h","4 unidades"],"correctAnswer":"4 km/h","misconceptions":{"9 km/h":["SAME_DIRECTION_SPEEDS_MUST_BE_SUBTRACTED"]},"position":2},{"id":"v5-physics-relative-speed-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":